import{_ as a,o as s,c as i,a3 as o}from"./chunks/framework.DLTBzH1I.js";const k=JSON.parse('{"title":"How to check repo conformance","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/check-repo-conformance.md","filePath":"how-to/check-repo-conformance.md"}'),t={name:"how-to/check-repo-conformance.md"};function c(r,e,d,n,l,h){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-to-check-repo-conformance" tabindex="-1">How to check repo conformance <a class="header-anchor" href="#how-to-check-repo-conformance" aria-label="Permalink to &quot;How to check repo conformance&quot;">​</a></h1><p><code>mimus standard</code> diffs a repo against declarative conformance specs — the org&#39;s way of saying &quot;every repo carries the same floor&quot; without a script per repo. Specs are TOML/YAML/JSON documents naming a <code>family</code>, <code>match</code> globs, a <code>severity</code>, and the expected file set; anything tracked in the repo that no spec covers is an <code>unlisted</code> violation.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../tamias</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../specs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../tamias/specs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./specs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><ul><li><code>--spec</code> takes a spec <strong>file or directory</strong> and is repeatable. Specs whose <code>match</code> globs don&#39;t cover the repo name are skipped; an empty <code>match</code> applies to every repo.</li><li>Repo enumeration prefers <code>git ls-files</code> — only tracked files are checked, so <code>target/</code> and other generated dirs need no carve-outs.</li><li>Exit <code>1</code> when any <code>fail</code>-severity spec reports violations; <code>warn</code> specs report but never gate.</li></ul><h2 id="what-a-spec-checks" tabindex="-1">What a spec checks <a class="header-anchor" href="#what-a-spec-checks" aria-label="Permalink to &quot;What a spec checks&quot;">​</a></h2><p>Three tiers, all declarative:</p><ol><li><strong>File set</strong> — exact <code>files</code> paths and <code>dirs</code> are required (missing → violation); glob <code>files</code> entries, <code>cover</code>, and <code>cover_dirs</code> whitelist tracked paths for the <code>unlisted</code> check without ever being required themselves. Coverage is unioned across every matched spec: a file covered by <em>any</em> spec is listed.</li><li><strong>Predicates</strong> — <code>[path.&quot;&lt;glob&gt;&quot;]</code> tables (<code>exists</code>, <code>contains</code>, <code>regex</code>) and <code>[git]</code> claims (<code>untracked</code> globs flag untracked-but-not-ignored files).</li><li><strong>Providers</strong> — <code>[providers.&lt;ns&gt;]</code> tables dispatch to a registered <code>StandardProvider</code>. Built in: <code>cargo</code> (org-local <code>[patch]</code> enforcement), <code>repo</code> (bupha.toml name/dir drift), <code>lasius</code>, <code>kuda</code>, <code>sturn</code>, <code>myco</code>, <code>cypera</code>. An unregistered namespace degrades to a <code>provider-unavailable</code> <strong>warn</strong> — never a hard fail.</li></ol><h2 id="reading-the-output" tabindex="-1">Reading the output <a class="header-anchor" href="#reading-the-output" aria-label="Permalink to &quot;Reading the output&quot;">​</a></h2><p>Each row is <code>(family, severity, violations)</code> — <code>missing</code> (required files absent), <code>unlisted</code> (tracked files no spec covers), <code>predicate</code> (path/git claim failures), and <code>provider</code> findings. <code>--format json</code> emits the same rows machine-readably for CI.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> specs/base.toml</span></span></code></pre></div><p>against a repo that meets the floor prints its matched families and no <code>fail</code> violations; point <code>--spec</code> at a spec with a deliberately absent <code>files</code> entry to see a <code>missing</code> violation fire.</p><h2 id="deeper" tabindex="-1">Deeper <a class="header-anchor" href="#deeper" aria-label="Permalink to &quot;Deeper&quot;">​</a></h2><ul><li><a href="./../reference/cli.html#mimus-standard">CLI reference</a> — full flag list</li><li><a href="./../explanation/architecture.html">Architecture</a> — where the spec tier sits among the checkers</li><li>Org usage: <code>specs/base.toml</code> is the fleet floor; per-repo specs live in <code>&lt;repo&gt;/specs/</code> and compose via union matching</li></ul>`,15)])])}const g=a(t,[["render",c]]);export{k as __pageData,g as default};
